import { HorizontalDivider } from "@hunt/puzzle-components";
import { Button } from "@hunt/shadcn";
import React from "react";
import q1a from "./assets/1-a.png";
import q1b from "./assets/1-b.png";
import q10a from "./assets/10-a.png";
import q10b from "./assets/10-b.png";
import q11a from "./assets/11-a.png";
import q11b from "./assets/11-b.png";
import q12a from "./assets/12-a.png";
import q12b from "./assets/12-b.png";
import q13a from "./assets/13-a.png";
import q13b from "./assets/13-b.png";
import q2a from "./assets/2-a.png";
import q2b from "./assets/2-b.png";
import q3a from "./assets/3-a.png";
import q3b from "./assets/3-b.png";
import q4a from "./assets/4-a.png";
import q4b from "./assets/4-b.png";
import q5a from "./assets/5-a.png";
import q5b from "./assets/5-b.png";
import q6a from "./assets/6-a.png";
import q6b from "./assets/6-b.png";
import q7a from "./assets/7-a.png";
import q7b from "./assets/7-b.png";
import q8a from "./assets/8-a.png";
import q8b from "./assets/8-b.png";
import q9a from "./assets/9-a.png";
import q9b from "./assets/9-b.png";
import { evaluateSubmission } from "./client-evaluation";

type Answer = "a" | "b" | undefined;

const QUESTIONS = [
  {
    prompt: ["Kiki", "Bouba"],
    a: { image: q1a, description: "An object with points protruding from it." },
    b: { image: q1b, description: "An object with bulbous protrusions." },
  },
  {
    prompt: ["Goobaw", "Norlib"],
    a: { image: q2a, description: "A tall narrow object with a lumpy top." },
    b: { image: q2b, description: "A short round object with a lumpy bottom." },
  },
  {
    prompt: ["Uumwam", "Ehtt"],
    a: { image: q3a, description: "A wide round object." },
    b: { image: q3b, description: "A narrow tall object" },
  },
  {
    prompt: ["Jarb", "Fancy Jarb"],
    a: { image: q4a, description: "A three-dimensional cylinder" },
    b: {
      image: q4b,
      description: "A three-dimensional cylinder with a tophat and monocle",
    },
  },
  {
    prompt: ["Wissiyesh", "Dumur"],
    a: { image: q5a, description: "A trapezoidal object with a wide bottom" },
    b: {
      image: q5b,
      description:
        "A leaning, vaguely triangular object that curls over at the top",
    },
  },
  {
    prompt: ["Thipech", "Onura"],
    a: {
      image: q6a,
      description: "Many concentric arcs around a central point",
    },
    b: { image: q6b, description: "Many perpendicular lines" },
  },
  {
    prompt: ["Lack", "Poang"],
    a: {
      image: q7a,
      description: "A rectangular object with four downward protrusions",
    },
    b: { image: q7b, description: "A squiggly object" },
  },
  {
    prompt: ["Alomo", "Vachtuf"],
    a: { image: q8a, description: "A donut-shaped object" },
    b: {
      image: q8b,
      description: "Two objects, each jagged on one end.",
    },
  },
  {
    prompt: ["Hiffoo", "Mrolt"],
    a: { image: q9a, description: "A gear-like object" },
    b: {
      image: q9b,
      description:
        "Several circles, with the larger circles tending to the bottom",
    },
  },
  {
    prompt: ["Spinch", "Qunch"],
    a: { image: q10a, description: "A leaf-like object with a face" },
    b: {
      image: q10b,
      description: "A leaf-like object with a concerning face",
    },
  },
  {
    prompt: ["Yucludae", "Rashikatti"],
    a: { image: q11a, description: "Several clusters of dots" },
    b: { image: q11b, description: "A scattering of dots" },
  },
  {
    prompt: ["Isofi", "Zohng"],
    a: {
      image: q12a,
      description: "A shaded region with a small rectangle cut out",
    },
    b: { image: q12b, description: "A rectangle without a bottom" },
  },
  {
    prompt: ["Xurchog", "Churm"],
    a: {
      image: q13a,
      description:
        "A wide-on-top trapezoid with a small triangle cut out from the bottom",
    },
    b: {
      image: q13b,
      description: "Short lines approximately radiating from a central point",
    },
  },
];

const createInitialAnswers = () =>
  new Array<Answer>(QUESTIONS.length).fill(undefined);

const createShuffledOrder = () => {
  const rest = QUESTIONS.map((_, index) => index).slice(1);
  for (let i = rest.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    const tmp = rest[i];
    rest[i] = rest[j];
    rest[j] = tmp;
  }
  return [0, ...rest];
};

const createRandomizedPrompts = () => {
  return QUESTIONS.map(() => Math.random() < 0.5);
};

const Puzzle = () => {
  const [answers, setAnswers] = React.useState<Answer[]>(createInitialAnswers);
  const [displayOrder, setDisplayOrder] =
    React.useState<number[]>(createShuffledOrder);
  const [askFirst, setAskFirst] = React.useState<boolean[]>(
    createRandomizedPrompts,
  );

  const [finalClue, setFinalClue] = React.useState<string[] | undefined>(
    undefined,
  );
  const [evaluation, setEvaluation] = React.useState<string | undefined>(
    undefined,
  );
  const handleSelect = (questionIndex: number, choice: "a" | "b") => {
    setAnswers((prev) => {
      const next = [...prev];
      next[questionIndex] = choice;
      return next;
    });
  };

  const handleReset = () => {
    setAnswers(createInitialAnswers());
    setDisplayOrder(createShuffledOrder());
    setAskFirst(createRandomizedPrompts());
    setFinalClue(undefined);
    setEvaluation(undefined);
  };

  const isComplete = answers.every((answer) => answer !== undefined);

  const handleSubmit = () => {
    const submission = answers.map((selection, index) => {
      if (selection === undefined) return undefined;
      // If we asked for the first name, answer is correct as-is
      // If we asked for the second name, flip the answer
      const normalized = askFirst[index]
        ? selection
        : selection === "a"
          ? "b"
          : "a";
      return normalized;
    });

    try {
      const result = evaluateSubmission(submission);
      setEvaluation(result.evaluation);
      setFinalClue(result.finalClue);
    } catch (error) {
      console.error("Evaluation failed:", error);
    }
  };

  return (
    <div className="flex flex-col items-center gap-4">
      {!finalClue &&
        displayOrder.map((questionIndex, displayIndex) => {
          const question = QUESTIONS[questionIndex];
          const previousQuestionIndex = displayOrder[displayIndex - 1];
          const isUnlocked =
            displayIndex === 0 || answers[previousQuestionIndex] !== undefined;
          if (!isUnlocked) {
            return null;
          }

          const selected = answers[questionIndex];

          const whichToAsk = askFirst[questionIndex]
            ? question.prompt[0]
            : question.prompt[1];

          return (
            <React.Fragment key={questionIndex}>
              {displayIndex > 0 && <HorizontalDivider />}
              <h3>
                {"This is "}
                <strong className="text-blue-500">{question.prompt[0]}</strong>
                {" and "}
                <strong className="text-blue-500">{question.prompt[1]}</strong>.
                Which is <strong className="text-blue-500">{whichToAsk}</strong>
                ?
              </h3>
              <div style={{ display: "flex", gap: "1rem" }}>
                <button
                  type="button"
                  onClick={() => {
                    handleSelect(questionIndex, "a");
                  }}
                  aria-pressed={selected === "a"}
                  style={{
                    border:
                      selected === "a" ? "2px solid #0070f3" : "1px solid #ccc",
                    padding: "0.5rem",
                    cursor: "pointer",
                    background: "transparent",
                  }}
                >
                  <img
                    src={question.a.image}
                    alt={question.a.description}
                    style={{ maxWidth: "200px", height: "auto" }}
                  />
                </button>
                <button
                  type="button"
                  onClick={() => {
                    handleSelect(questionIndex, "b");
                  }}
                  aria-pressed={selected === "b"}
                  style={{
                    border:
                      selected === "b" ? "2px solid #0070f3" : "1px solid #ccc",
                    padding: "0.5rem",
                    cursor: "pointer",
                    background: "transparent",
                  }}
                >
                  <img
                    src={question.b.image}
                    alt={question.b.description}
                    style={{ maxWidth: "200px", height: "auto" }}
                  />
                </button>
              </div>
            </React.Fragment>
          );
        })}
      {isComplete && (
        <>
          {!finalClue && (
            <div
              style={{ marginTop: "1.5rem", display: "flex", gap: "0.75rem" }}
            >
              <Button
                onClick={() => {
                  handleSubmit();
                }}
              >
                Submit
              </Button>
            </div>
          )}
          {finalClue && (
            <>
              <h3>{evaluation}</h3>
              <div className="flex flex-wrap gap-2">
                {finalClue.map((image) => (
                  <img
                    src={image}
                    alt=""
                    style={{ maxWidth: "150px", height: "auto" }}
                    key={image}
                  />
                ))}
              </div>
              <Button onClick={handleReset}>Try again</Button>
              <HorizontalDivider />
              <div className="mt-4">
                <h4 className="text-sm text-gray-600 mb-2">Your choices:</h4>
                <div className="flex flex-wrap gap-4">
                  {displayOrder.map((questionIndex) => {
                    const question = QUESTIONS[questionIndex];
                    const answer = answers[questionIndex];
                    if (answer === undefined) {
                      return null;
                    }
                    const whichToAsk = askFirst[questionIndex]
                      ? question.prompt[0]
                      : question.prompt[1];
                    const otherName = askFirst[questionIndex]
                      ? question.prompt[1]
                      : question.prompt[0];
                    const selectedImage =
                      answer === "a" ? question.a.image : question.b.image;
                    const selectedDescription =
                      answer === "a"
                        ? question.a.description
                        : question.b.description;
                    const notSelectedImage =
                      answer === "a" ? question.b.image : question.a.image;
                    const notSelectedDescription =
                      answer === "a"
                        ? question.b.description
                        : question.a.description;
                    return (
                      <div
                        key={`choice-${questionIndex}`}
                        className="flex gap-2"
                      >
                        <div className="flex flex-col items-center">
                          <img
                            src={selectedImage}
                            alt={selectedDescription}
                            style={{ maxWidth: "75px", height: "auto" }}
                          />
                          <span className="text-xs text-gray-600 mt-1">
                            {whichToAsk}
                          </span>
                        </div>
                        <div className="flex flex-col items-center">
                          <img
                            src={notSelectedImage}
                            alt={notSelectedDescription}
                            style={{
                              maxWidth: "75px",
                              height: "auto",
                            }}
                          />
                          <span className="text-xs text-gray-600 mt-1">
                            {otherName}
                          </span>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            </>
          )}
        </>
      )}
    </div>
  );
};

export default Puzzle;
